-- =============================================================================
-- Studuel — Migration 339 : EPS COLLÈGE — LE PROGRAMME COMMUN AUX QUATRE NIVEAUX (8 fiches)
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 339 --modules sport-college
--
-- CONSTAT : l'EPS n'avait que TROIS chapitres au collège — trois en 6e, trois
-- partagés par la 5e, la 4e et la 3e — soit trois fiches pour quatre années.
-- Cette migration installe 8 fiches sous 3 chapitres, sur les QUATRE niveaux, et
-- retire les chapitres génériques.
-- UN SEUL MODULE POUR QUATRE NIVEAUX : contrairement aux autres matières, l'EPS ne
-- change pas de découpage entre le cycle 3 et le cycle 4 — ce sont les mêmes quatre
-- champs d'apprentissage de la 6e à la 3e, ce qui varie étant le niveau d'exigence
-- dans la PRATIQUE, donc précisément ce qui ne se révise pas sur écran.
-- PÉRIMÈTRE ASSUMÉ : ce module ne prétend pas remplacer le cours. Une matière
-- pratique ne s'apprend pas devant un téléphone. Il couvre ce qui est réellement
-- évaluable à l'écrit et utile — règles, rôles sociaux, corps à l'effort,
-- échauffement, sécurité, hygiène de vie.
--
-- Cette migration apporte : 32 chapitres, 32 leçons,
-- 32 quiz et 256 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · le contenu est écrit par CYCLE (le programme d’EPS du cycle 4 vaut pour
--    la 5e, la 4e et la 3e) puis dupliqué sur chaque niveau du cycle : c’est
--    ainsi que sont écrits les programmes de l’Éducation nationale ;
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [sport] La colonne chapters.theme (migration 234) porte le chapitre du programme, et
-- [sport] l'INSERT l'écrit pour les 8 fiches × 4 niveaux. Elle est REPRISE ici en ADD
-- [sport] COLUMN IF NOT EXISTS parce qu'on ne peut pas garantir que la 234 soit passée.
-- [sport] Le GRANT n'est pas décoratif : la migration 182 a révoqué le SELECT de table sur
-- [sport] chapters et ne l'a rendu que colonne par colonne.
ALTER TABLE public.chapters ADD COLUMN IF NOT EXISTS theme TEXT;
GRANT SELECT (theme) ON public.chapters TO anon;
GRANT SELECT (theme) ON public.chapters TO authenticated;

-- [sport] Les chapitres hérités partent, sur les QUATRE niveaux du collège.
-- [sport] 
-- [sport] LE REPÈRE EST theme IS NULL, PAS LE TITRE : les 8 fiches neuves portent leur
-- [sport] chapitre de programme dès l'INSERT, les anciennes n'en ont aucun. Le ménage
-- [sport] tourne AVANT les insertions et ne peut donc jamais mordre sur les neuves.
-- [sport] LE FILTRE DE NIVEAU BORNE AU COLLÈGE : 6e, 5e, 4e et 3e — pas le lycée, dont les
-- [sport] trois fiches d'EPS relèvent d'un autre programme et ne sont pas traitées ici. Un
-- [sport] IN (...) trop large les effacerait sans rien mettre à la place.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'sport'
   AND c.level IN ('6e', '5e', '4e', '3e')
   AND c.theme IS NULL;

DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'sport'
   AND c.level IN ('6e', '5e', '4e', '3e')
   AND c.theme IS NULL;

DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'sport'
   AND c.level IN ('6e', '5e', '4e', '3e')
   AND c.theme IS NULL;

