-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('768e82c9-4841-5959-b8bc-7c9cfe45d296'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'Combien de champs d’apprentissage compte le programme d’EPS ?', 'mcq', '["Quatre","Deux","Six","Trois"]'::jsonb, 0, 'Ce sont quatre familles de problèmes à résoudre.', 1),
    ('142d1f01-0151-57c2-9488-886aac5963f0'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'Quel champ concerne l’athlétisme et la natation de vitesse ?', 'mcq', '["Produire une performance mesurée","Adapter son déplacement","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Il s’agit de se dépasser et de mesurer son progrès.', 2),
    ('91266381-5fd0-5e4a-8c21-30d6f60e0bd5'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'À quel champ appartient l’escalade ?', 'mcq', '["Adapter son déplacement à des environnements variés","Produire une performance mesurée","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Le milieu y est incertain.', 3),
    ('8aa4a03e-39b4-505d-9b0e-86be7e765f1b'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'Quel champ regroupe la danse et l’acrosport ?', 'mcq', '["S’exprimer devant les autres par une prestation artistique","Produire une performance","Conduire un affrontement","Adapter son déplacement"]'::jsonb, 0, 'Créer, répéter, présenter à un public.', 4),
    ('f71d34df-82d7-510a-9a77-bd582c651bc6'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'À quel champ appartiennent le badminton et le handball ?', 'mcq', '["Conduire et maîtriser un affrontement","Produire une performance mesurée","S’exprimer devant les autres","Adapter son déplacement"]'::jsonb, 0, 'Il faut décider vite dans un rapport de force.', 5),
    ('c1365939-9919-5854-980c-537afea24192'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'Qu’évalue-t-on en EPS ?', 'mcq', '["La progression, la méthode, les rôles tenus et le respect, pas seulement la performance","Uniquement le chronomètre","Uniquement la force","La présence seule"]'::jsonb, 0, 'La performance n’est qu’un critère parmi d’autres.', 6),
    ('e2f97448-852a-5475-a409-ab314ca36e36'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'Qu’est-ce que l’AS du collège ?', 'mcq', '["L’association sportive, ouverte à tous le mercredi","Une compétition réservée aux meilleurs","Un examen","Une note de fin d’année"]'::jsonb, 0, 'Elle permet de découvrir d’autres activités.', 7),
    ('3a24b8c6-50e0-5ac3-a5de-ad845097c55b'::uuid, '7a0d4c6c-03c6-5640-bc42-ac50c89e6360'::uuid, 'Le programme d’EPS est une liste de sports à pratiquer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un parcours organisé autour de quatre types de problèmes.', 8),
    ('1133caeb-d0a9-50f4-9d55-44536f1df8d5'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'Qu’est-ce qui distingue un élève qui progresse ?', 'mcq', '["Sa méthode, pas son niveau de départ","Son talent naturel","Sa taille","Sa force initiale"]'::jsonb, 0, 'On progresse par la répétition organisée.', 1),
    ('43c03e10-2dd3-5c96-8b22-deac2120ec50'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'Qu’est-ce qu’un bon objectif ?', 'mcq', '["Précis, mesurable et atteignable","Ambitieux et vague","Fixé par le professeur seul","Le plus élevé possible"]'::jsonb, 0, '« Courir 8 minutes sans m’arrêter ».', 2),
    ('9ca16929-ae77-5b38-b643-577e8a486752'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'Pourquoi mesurer son niveau de départ ?', 'mcq', '["Sans mesure initiale, le progrès reste invisible","Pour se comparer aux autres","Pour être noté","Ce n’est pas utile"]'::jsonb, 0, 'Un progrès invisible décourage.', 3),
    ('9aff901f-e8df-54ca-9f8d-a8ce8a7ac0a3'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'Qu’est-ce qui fait le plus progresser ?', 'mcq', '["Trois séances courtes par semaine","Une seule longue séance","L’intensité maximale à chaque fois","Le repos complet"]'::jsonb, 0, 'Le corps s’adapte entre les séances.', 4),
    ('5471afa5-27d3-5cd7-8003-789f34257217'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'Qu’est-ce que la surcompensation ?', 'mcq', '["L’adaptation du corps entre les séances","Un excès d’entraînement","Une blessure","Un échauffement long"]'::jsonb, 0, 'C’est pourquoi la régularité prime.', 5),
    ('bd5aeded-7b7f-5a31-bf8e-0ebd20edd868'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'Quel est le rôle de l’erreur dans l’apprentissage moteur ?', 'mcq', '["Elle en fait partie : un geste s’automatise après de nombreux échecs","Elle doit être évitée","Elle prouve un manque de talent","Elle n’a aucun rôle"]'::jsonb, 0, 'Refuser de rater, c’est refuser d’apprendre.', 6),
    ('762eccdd-1c0b-5d82-9ab0-26968bdf515f'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'Pourquoi se filmer ou se faire observer ?', 'mcq', '["Voir le geste de l’extérieur corrige plus vite que la sensation","Pour se comparer","Pour être noté","Pour le plaisir"]'::jsonb, 0, 'La sensation interne trompe souvent.', 7),
    ('754e43b7-acbd-5b76-abb3-8bf88b1b6740'::uuid, '88e0022a-d848-5518-b513-d9b6f449cece'::uuid, 'On progresse surtout grâce à des dispositions naturelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la méthode et la régularité qui font la différence.', 8),
    ('a3d3101c-0454-59d4-b5c0-2ac1dbd47792'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'À quoi sert principalement l’échauffement ?', 'mcq', '["Préparer le corps à l’effort et réduire le risque de blessure","Fatiguer avant l’effort","Gagner du temps","Impressionner l’adversaire"]'::jsonb, 0, 'C’est la partie qui protège toutes les autres.', 1),
    ('79663af9-93b9-5f29-ac4c-d1dfc0adcc19'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'De combien la température musculaire monte-t-elle ?', 'mcq', '["De 1 à 2 °C","De 10 °C","Elle ne change pas","De 5 °C"]'::jsonb, 0, 'Le muscle devient plus élastique.', 2),
    ('231d4ac4-7914-5b78-b9ce-ed6fd2ef54ea'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'Quels sont les trois temps de l’échauffement ?', 'mcq', '["Général, articulaire, spécifique","Étirements, sprint, repos","Course, saut, lancer","Léger, moyen, intense"]'::jsonb, 0, 'Du général vers le spécifique.', 3),
    ('6547668a-eb72-5b22-9ca0-92e97d0f8c0f'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'Combien de temps dure l’échauffement général ?', 'mcq', '["5 à 10 minutes","30 secondes","30 minutes","1 minute"]'::jsonb, 0, 'Activité douce et continue.', 4),
    ('a35ac9f0-2a1e-547a-9f0f-7b421e07e3fa'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'Quand faut-il faire les étirements longs ?', 'mcq', '["Après l’effort, au retour au calme","Avant l’effort","Pendant l’effort","Jamais"]'::jsonb, 0, 'Avant, ils diminuent temporairement la force.', 5),
    ('3f1af8cf-ae1f-5a27-b3fa-fd193f442532'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'Dans quel sens progresse un échauffement ?', 'mcq', '["Du lent vers le rapide et du général vers le spécifique","Du rapide vers le lent","Peu importe l’ordre","Du spécifique vers le général"]'::jsonb, 0, 'Commencer par un sprint blesse.', 6),
    ('1bbd2182-8d87-59bf-bcce-67e69a3328b3'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'À quoi sert le retour au calme ?', 'mcq', '["Faire redescendre le rythme cardiaque et faciliter la récupération","Gagner des points","Rien de particulier","Se réchauffer"]'::jsonb, 0, 'Environ 5 minutes d’activité douce.', 7),
    ('ceb21db4-8221-5cfd-bfe8-6e533ad17ccc'::uuid, '0f136b59-dc57-5e33-8cdf-1e75de2d8cf4'::uuid, 'Les étirements avant l’effort préviennent les blessures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les étirements statiques avant l’effort diminuent la force sans protéger.', 8),
    ('dac802a5-b88c-50fb-994e-de9e190518f6'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'Que réclament les muscles pendant l’effort ?', 'mcq', '["Plus de dioxygène et de nutriments","Moins de sang","Du dioxyde de carbone","Du repos immédiat"]'::jsonb, 0, 'Le cœur et la respiration s’accélèrent pour les fournir.', 1),
    ('4ed6a81c-007d-5dbd-86d7-36b3dc3fd259'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'Qu’est-ce que le régime aérobie ?', 'mcq', '["Un effort modéré et long où le dioxygène suffit","Un sprint","Un effort sans respiration","Un effort au repos"]'::jsonb, 0, 'On peut parler en courant.', 2),
    ('228c142e-2c85-5648-9b14-2ab661524d2b'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'Que produit le corps en anaérobie ?', 'mcq', '["De l’acide lactique","Du dioxygène","De l’eau seulement","Du glucose"]'::jsonb, 0, 'D’où les jambes qui brûlent.', 3),
    ('763c8822-f378-5d8a-9f48-f894bb4254be'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'Comment estimer sa fréquence cardiaque maximale ?', 'mcq', '["220 moins l’âge","200 plus l’âge","Le double du pouls au repos","150 pour tout le monde"]'::jsonb, 0, 'À 13 ans, environ 207.', 4),
    ('ce7e611e-2b49-5718-8bc4-475fbbdc54a3'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'À quelle intensité travaille-t-on l’endurance ?', 'mcq', '["Entre 60 et 75 % de la FCmax","À 100 %","À 30 %","Peu importe"]'::jsonb, 0, 'Une allure où l’on peut encore parler.', 5),
    ('35230058-ce31-5ea0-a909-e31e15364d58'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'Quel effet l’entraînement régulier a-t-il au repos ?', 'mcq', '["Il fait baisser le rythme cardiaque","Il l’augmente","Il ne change rien","Il augmente la température"]'::jsonb, 0, 'Le cœur envoie plus de sang à chaque battement.', 6),
    ('9dc9da6d-eabf-5333-8b6e-314871ddafa1'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'Quand faut-il boire ?', 'mcq', '["Avant, pendant et après l’effort","Seulement après","Seulement quand on a soif","Le moins possible"]'::jsonb, 0, 'La soif apparaît quand la déshydratation a commencé.', 7),
    ('da3f64c1-efc3-5547-a385-965d884e0a05'::uuid, '515cb700-2290-5fba-8b7d-25584b5a2310'::uuid, 'Une douleur vive pendant l’effort doit être surmontée par courage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une information : on s’arrête et on prévient.', 8),
    ('581d7a1c-839c-5ac7-aef6-9799d0fb967a'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'De combien d’heures de sommeil un adolescent a-t-il besoin ?', 'mcq', '["8 à 10 heures","5 à 6 heures","12 heures","7 heures maximum"]'::jsonb, 0, 'C’est pendant le sommeil que le corps répare et consolide.', 1),
    ('26cd89e5-d6a1-5b1e-8e54-245a71ce082e'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'Que fait le corps pendant le sommeil ?', 'mcq', '["Il répare les muscles et consolide les apprentissages","Il ne fait rien","Il brûle des calories seulement","Il digère uniquement"]'::jsonb, 0, 'Y compris les apprentissages moteurs.', 2),
    ('6e38cddd-0bc8-57d2-8a37-2593527d38ac'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'Pourquoi les écrans nuisent-ils au sommeil ?', 'mcq', '["La lumière bleue retarde la sécrétion de mélatonine","Ils chauffent la pièce","Ils font du bruit","Ils fatiguent les yeux seulement"]'::jsonb, 0, 'L’endormissement est décalé.', 3),
    ('4589741d-8d8f-52d8-af8a-73221cf1b659'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'Quel nutriment est le carburant principal de l’effort ?', 'mcq', '["Les glucides complexes","Les lipides","Les protéines","Les vitamines"]'::jsonb, 0, 'Pâtes, riz, pain, légumes secs.', 4),
    ('cf60fd6e-8576-5308-add8-a36b29d4494e'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'Quelle est la seule boisson indispensable ?', 'mcq', '["L’eau","Les boissons énergisantes","Le jus de fruit","Le lait"]'::jsonb, 0, 'Les boissons énergisantes sont inutiles et parfois dangereuses.', 5),
    ('77aead6a-313d-51ee-8ad1-7220e81834bc'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'Combien de minutes d’activité par jour l’OMS recommande-t-elle aux 5-17 ans ?', 'mcq', '["Au moins 60 minutes","15 minutes","30 minutes","2 heures"]'::jsonb, 0, 'Marcher et faire du vélo comptent.', 6),
    ('b505a75a-ae91-5db4-b377-335a93df21fa'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'La sédentarité est-elle compensée par une séance de sport ?', 'mcq', '["Non, c’est un risque distinct du manque de sport","Oui, entièrement","Oui, si la séance est longue","La question ne se pose pas"]'::jsonb, 0, 'Se lever quelques minutes chaque heure compte.', 7),
    ('412be012-9ca8-5332-98b5-52fdf92ae6bb'::uuid, '8e52958b-2a6c-588a-830d-915da3f62882'::uuid, 'Un adolescent sportif a besoin de compléments protéinés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une alimentation variée suffit ; à cet âge, le premier facteur est le sommeil.', 8),
    ('2ae864d6-73e8-5b39-abe5-bdcef4aeed43'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Pourquoi les rôles sont-ils évalués en EPS ?', 'mcq', '["Ils demandent de comprendre l’activité, pas seulement de la subir","Pour occuper les élèves dispensés","Pour gagner du temps","Ils ne sont pas évalués"]'::jsonb, 0, 'Au même titre que la performance.', 1),
    ('e3fbb4ce-8034-5f0d-a06c-b1411f751209'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Que suppose le rôle d’arbitre ?', 'mcq', '["Connaître la règle, décider vite et assumer la contestation","Être le meilleur joueur","Être le plus âgé","Rester silencieux"]'::jsonb, 0, 'Un arbitre qui hésite perd le match.', 2),
    ('2256a6ec-311d-59dc-836a-4508a9996f12'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Que fait l’observateur ?', 'mcq', '["Il relève des données précises et chiffrées","Il donne son avis général","Il arbitre","Il ne fait rien"]'::jsonb, 0, '« 7 passes sur 10 » se travaille, « il a bien joué » non.', 3),
    ('d6ab9d96-c5a4-5189-95ba-9057332086ca'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Qu’est-ce qu’un bon conseil de coach ?', 'mcq', '["Précis et positif : « place-toi plus haut »","Général : « joue mieux »","Négatif mais franc","Silencieux"]'::jsonb, 0, 'Le conseil doit être actionnable.', 4),
    ('f71b0daf-acc9-57e9-b4b0-acc8deda3db5'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Que fait l’organisateur ?', 'mcq', '["Il installe le matériel, tient le score, équilibre les équipes","Il joue en premier","Il note les élèves","Il choisit l’activité"]'::jsonb, 0, 'Sans lui, la séance n’a pas lieu.', 5),
    ('4a689013-0110-52ca-98c1-ce00cad389a3'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Qu’apprend-on en arbitrant ?', 'mcq', '["Ce qu’on ressent quand on est contesté","À courir plus vite","À marquer plus de points","Rien de particulier"]'::jsonb, 0, 'Cela change durablement la façon de jouer.', 6),
    ('34068c8c-2077-5653-8f1c-c76bdbe65843'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Quelles compétences transférables les rôles développent-ils ?', 'mcq', '["Décider sous pression, formuler un retour, organiser un groupe","La vitesse de course","La force musculaire","La souplesse"]'::jsonb, 0, 'Elles servent bien au-delà du gymnase.', 7),
    ('e99a2f2a-8f7c-5798-aab9-9c45430e5a33'::uuid, '3f0a9c2d-e24e-5cbd-8f06-c067348e5ec6'::uuid, 'Contester systématiquement l’arbitre fait partie du jeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela désorganise la séance et rend le rôle intenable.', 8),
    ('fd4d9d33-3fa6-57f9-a31c-32489d0b3c5f'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'À quoi sert la règle dans un sport ?', 'mcq', '["Elle crée le jeu en fixant ce qui compte","Elle empêche de jouer librement","Elle avantage les plus forts","Elle sert à punir"]'::jsonb, 0, 'Sans règle commune, il n’y a pas de match.', 1),
    ('d8cbd0fa-2269-5b52-bbfb-9d1dfed9ec78'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'Qu’est-ce que le fair-play ?', 'mcq', '["Respecter la règle et l’adversaire même sans y être obligé","Gagner à tout prix","Obéir à l’arbitre","Ne jamais protester"]'::jsonb, 0, 'Il commence là où finit la surveillance.', 2),
    ('9aa58bf5-cffc-5845-94ac-7abdff8f60a0'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'Quelles sont les trois familles de règles ?', 'mcq', '["Règles de but, d’espace et de temps, de sécurité","Règles écrites, orales, tacites","Règles d’attaque, de défense, de repos","Règles simples, moyennes, complexes"]'::jsonb, 0, 'Chacune joue un rôle différent.', 3),
    ('bcfeb3f2-dc07-53b5-8e38-a844010b37db'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'Que perd le mauvais perdant ?', 'mcq', '["La possibilité d’identifier ce qu’il y avait à corriger","Des points","Le respect de l’arbitre","Rien"]'::jsonb, 0, 'Chercher une excuse empêche de progresser.', 4),
    ('3175d3f8-2cfa-5cda-9d84-5631248491c6'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'Que prouve une victoire obtenue en trichant ?', 'mcq', '["Rien, pas même à celui qui triche","Qu’on est le meilleur","Qu’on est malin","Que la règle est mauvaise"]'::jsonb, 0, 'Elle fait gagner un match et perdre l’essentiel.', 5),
    ('8b4f4741-49fe-546b-8426-c9ae2f9c9a86'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'Pourquoi le dopage est-il interdit ?', 'mcq', '["Il fausse la compétition et met la santé en danger","Il coûte cher","Il est difficile à obtenir","Il ne fonctionne pas"]'::jsonb, 0, 'Effets sur le cœur, les hormones, le psychisme.', 6),
    ('eabd946a-b298-5a1e-9bbf-a0b5fdb7b8c6'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'Quelles sont les trois valeurs olympiques ?', 'mcq', '["Excellence, amitié, respect","Force, vitesse, endurance","Victoire, gloire, argent","Discipline, silence, obéissance"]'::jsonb, 0, 'Elles dépassent la performance.', 7),
    ('144ed177-567a-5f78-88c3-ebd6b38dac1a'::uuid, '9906a3e6-879e-5646-bff6-08c32b37e521'::uuid, 'Respecter la règle uniquement quand l’arbitre regarde, c’est du fair-play.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est de l’obéissance ; le fair-play commence quand personne ne surveille.', 8),
    ('d0381788-016e-53ab-9d5f-453f51bde60e'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Pourquoi retire-t-on les bijoux avant une séance ?', 'mcq', '["Ils accrochent et blessent","Ils font du bruit","Ils ralentissent","C’est une tradition"]'::jsonb, 0, 'Bagues, colliers, montres, piercings.', 1),
    ('2244fbc2-6a49-5bd6-b008-d14045ea47de'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Que signale une consigne de sécurité ?', 'mcq', '["La trace d’un accident réel qu’on ne veut pas revoir","Une précaution théorique","Une contrainte administrative","Une préférence du professeur"]'::jsonb, 0, 'Elles ne sont pas négociables.', 2),
    ('6047a146-e2df-5046-b81c-ec1ef29bb8dc'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Qu’est-ce qu’un claquage ?', 'mcq', '["Une douleur musculaire brutale en plein effort","Une articulation tordue","Un os cassé","Un vertige"]'::jsonb, 0, 'L’entorse concerne l’articulation.', 3),
    ('825d464d-ba10-57d4-ab36-a43a73746423'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Que signifie le protocole RICE ?', 'mcq', '["Repos, glace, compression, élévation","Repos, immobilité, chaleur, examen","Respirer, isoler, calmer, évacuer","Rien de précis"]'::jsonb, 0, 'La glace jamais à même la peau.', 4),
    ('1a12b27b-e66f-5cfa-a968-1dfb23eb8b16'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Quel est l’ordre des gestes en cas d’accident ?', 'mcq', '["Protéger, alerter, secourir","Secourir, alerter, protéger","Alerter, protéger, secourir","Appeler les parents d’abord"]'::jsonb, 0, 'Sans se mettre soi-même en danger.', 5),
    ('43b05249-a0d6-55dc-a7d6-485d424e3032'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Quel numéro appeler pour une urgence médicale ?', 'mcq', '["Le 15","Le 17","Le 114","Le 119"]'::jsonb, 0, 'Le 112 fonctionne partout en Europe.', 6),
    ('42809e7a-6ca1-593a-84ce-95899d6ea6ad'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Qu’apprend-on au PSC1 ?', 'mcq', '["Position latérale de sécurité, massage cardiaque, défibrillateur","Les règles du basket","L’échauffement","La natation"]'::jsonb, 0, 'Elle s’obtient dès le collège.', 7),
    ('1e05ef54-7170-5434-b9cf-741bb47ff721'::uuid, '2d1290cc-1394-503b-bb2d-680fa142a77a'::uuid, 'Au téléphone avec les secours, on peut raccrocher dès qu’on a donné l’adresse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne raccroche jamais le premier.', 8),
    ('7b6f1cbc-9f12-5e72-97be-1094326437cc'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Combien de champs d’apprentissage compte le programme d’EPS ?', 'mcq', '["Quatre","Deux","Six","Trois"]'::jsonb, 0, 'Ce sont quatre familles de problèmes à résoudre.', 1),
    ('9f24c80a-16d2-5efb-96d9-11b5a5215768'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Quel champ concerne l’athlétisme et la natation de vitesse ?', 'mcq', '["Produire une performance mesurée","Adapter son déplacement","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Il s’agit de se dépasser et de mesurer son progrès.', 2),
    ('89a0d70d-dd41-5849-b3dc-f465ead96a5d'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'À quel champ appartient l’escalade ?', 'mcq', '["Adapter son déplacement à des environnements variés","Produire une performance mesurée","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Le milieu y est incertain.', 3),
    ('01186ab0-c15f-5e4e-b49f-3abe40cd7db3'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Quel champ regroupe la danse et l’acrosport ?', 'mcq', '["S’exprimer devant les autres par une prestation artistique","Produire une performance","Conduire un affrontement","Adapter son déplacement"]'::jsonb, 0, 'Créer, répéter, présenter à un public.', 4),
    ('172581c6-4bcf-5c04-8b42-846bdc1b0d9d'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'À quel champ appartiennent le badminton et le handball ?', 'mcq', '["Conduire et maîtriser un affrontement","Produire une performance mesurée","S’exprimer devant les autres","Adapter son déplacement"]'::jsonb, 0, 'Il faut décider vite dans un rapport de force.', 5),
    ('8993fbd2-665c-5db3-b899-0d8db7055107'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Qu’évalue-t-on en EPS ?', 'mcq', '["La progression, la méthode, les rôles tenus et le respect, pas seulement la performance","Uniquement le chronomètre","Uniquement la force","La présence seule"]'::jsonb, 0, 'La performance n’est qu’un critère parmi d’autres.', 6),
    ('b7768cf1-a30b-5acf-ba28-dabca46e1f23'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Qu’est-ce que l’AS du collège ?', 'mcq', '["L’association sportive, ouverte à tous le mercredi","Une compétition réservée aux meilleurs","Un examen","Une note de fin d’année"]'::jsonb, 0, 'Elle permet de découvrir d’autres activités.', 7),
    ('75c102af-0b54-55b1-b9bc-2f65534055b3'::uuid, '9ae6d2b3-def9-5293-9548-b69ad7a1e0f5'::uuid, 'Le programme d’EPS est une liste de sports à pratiquer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un parcours organisé autour de quatre types de problèmes.', 8),
    ('e8ac37c8-b81f-58fb-9a9f-d6edc461e05e'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'Qu’est-ce qui distingue un élève qui progresse ?', 'mcq', '["Sa méthode, pas son niveau de départ","Son talent naturel","Sa taille","Sa force initiale"]'::jsonb, 0, 'On progresse par la répétition organisée.', 1),
    ('4b0259cc-80a9-5d8d-a9cd-98a1b413df68'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'Qu’est-ce qu’un bon objectif ?', 'mcq', '["Précis, mesurable et atteignable","Ambitieux et vague","Fixé par le professeur seul","Le plus élevé possible"]'::jsonb, 0, '« Courir 8 minutes sans m’arrêter ».', 2),
    ('e285b90d-bef5-5246-bf45-ffd44bf65430'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'Pourquoi mesurer son niveau de départ ?', 'mcq', '["Sans mesure initiale, le progrès reste invisible","Pour se comparer aux autres","Pour être noté","Ce n’est pas utile"]'::jsonb, 0, 'Un progrès invisible décourage.', 3),
    ('fb412215-7317-55c9-b1bc-26c39d9ddf40'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'Qu’est-ce qui fait le plus progresser ?', 'mcq', '["Trois séances courtes par semaine","Une seule longue séance","L’intensité maximale à chaque fois","Le repos complet"]'::jsonb, 0, 'Le corps s’adapte entre les séances.', 4),
    ('e07dcf3f-e242-5252-abdb-25985ab78bee'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'Qu’est-ce que la surcompensation ?', 'mcq', '["L’adaptation du corps entre les séances","Un excès d’entraînement","Une blessure","Un échauffement long"]'::jsonb, 0, 'C’est pourquoi la régularité prime.', 5),
    ('f4ac19e4-7948-50ec-9c20-4bf55bd17dbd'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'Quel est le rôle de l’erreur dans l’apprentissage moteur ?', 'mcq', '["Elle en fait partie : un geste s’automatise après de nombreux échecs","Elle doit être évitée","Elle prouve un manque de talent","Elle n’a aucun rôle"]'::jsonb, 0, 'Refuser de rater, c’est refuser d’apprendre.', 6),
    ('8f397966-c4b6-5105-8fe4-8b509930dc85'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'Pourquoi se filmer ou se faire observer ?', 'mcq', '["Voir le geste de l’extérieur corrige plus vite que la sensation","Pour se comparer","Pour être noté","Pour le plaisir"]'::jsonb, 0, 'La sensation interne trompe souvent.', 7),
    ('c81a9b09-8e51-50fc-9b63-22f0444ceed1'::uuid, 'ef1aeab3-42f0-52ee-9630-3500f82b4d3b'::uuid, 'On progresse surtout grâce à des dispositions naturelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la méthode et la régularité qui font la différence.', 8),
    ('a3e86314-891d-5d5b-aae7-6d58bd94ed2c'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'À quoi sert principalement l’échauffement ?', 'mcq', '["Préparer le corps à l’effort et réduire le risque de blessure","Fatiguer avant l’effort","Gagner du temps","Impressionner l’adversaire"]'::jsonb, 0, 'C’est la partie qui protège toutes les autres.', 1),
    ('5ffaabc8-321f-535e-8734-7d65f54e0186'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'De combien la température musculaire monte-t-elle ?', 'mcq', '["De 1 à 2 °C","De 10 °C","Elle ne change pas","De 5 °C"]'::jsonb, 0, 'Le muscle devient plus élastique.', 2),
    ('64c82d4f-93ed-56e9-a60d-e9f7b677d088'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'Quels sont les trois temps de l’échauffement ?', 'mcq', '["Général, articulaire, spécifique","Étirements, sprint, repos","Course, saut, lancer","Léger, moyen, intense"]'::jsonb, 0, 'Du général vers le spécifique.', 3),
    ('a8189406-40b8-5358-8930-f3ee0dc3f85c'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'Combien de temps dure l’échauffement général ?', 'mcq', '["5 à 10 minutes","30 secondes","30 minutes","1 minute"]'::jsonb, 0, 'Activité douce et continue.', 4),
    ('de5f395b-2d53-565d-810a-e7354989e4be'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'Quand faut-il faire les étirements longs ?', 'mcq', '["Après l’effort, au retour au calme","Avant l’effort","Pendant l’effort","Jamais"]'::jsonb, 0, 'Avant, ils diminuent temporairement la force.', 5),
    ('a3c0f7dc-325b-5b29-97f6-4bb3972b5996'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'Dans quel sens progresse un échauffement ?', 'mcq', '["Du lent vers le rapide et du général vers le spécifique","Du rapide vers le lent","Peu importe l’ordre","Du spécifique vers le général"]'::jsonb, 0, 'Commencer par un sprint blesse.', 6),
    ('979906dc-372b-5e0e-86fc-1533c230dad0'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'À quoi sert le retour au calme ?', 'mcq', '["Faire redescendre le rythme cardiaque et faciliter la récupération","Gagner des points","Rien de particulier","Se réchauffer"]'::jsonb, 0, 'Environ 5 minutes d’activité douce.', 7),
    ('8456dd47-483b-5038-bce0-d55e23221126'::uuid, '28fa8c08-1837-5291-b3ff-1245cae18f67'::uuid, 'Les étirements avant l’effort préviennent les blessures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les étirements statiques avant l’effort diminuent la force sans protéger.', 8),
    ('a3e38800-20e6-5f5f-8e3f-d644e20dbfee'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'Que réclament les muscles pendant l’effort ?', 'mcq', '["Plus de dioxygène et de nutriments","Moins de sang","Du dioxyde de carbone","Du repos immédiat"]'::jsonb, 0, 'Le cœur et la respiration s’accélèrent pour les fournir.', 1),
    ('4d422fff-03be-50e2-822f-e548605048ee'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'Qu’est-ce que le régime aérobie ?', 'mcq', '["Un effort modéré et long où le dioxygène suffit","Un sprint","Un effort sans respiration","Un effort au repos"]'::jsonb, 0, 'On peut parler en courant.', 2),
    ('eeb5d724-75ba-50a3-9c42-cbfaeee32cf1'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'Que produit le corps en anaérobie ?', 'mcq', '["De l’acide lactique","Du dioxygène","De l’eau seulement","Du glucose"]'::jsonb, 0, 'D’où les jambes qui brûlent.', 3),
    ('8a04e130-e030-5614-aa6f-ddde586230d9'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'Comment estimer sa fréquence cardiaque maximale ?', 'mcq', '["220 moins l’âge","200 plus l’âge","Le double du pouls au repos","150 pour tout le monde"]'::jsonb, 0, 'À 13 ans, environ 207.', 4),
    ('dce078a1-e605-5621-bbd1-4018db215676'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'À quelle intensité travaille-t-on l’endurance ?', 'mcq', '["Entre 60 et 75 % de la FCmax","À 100 %","À 30 %","Peu importe"]'::jsonb, 0, 'Une allure où l’on peut encore parler.', 5),
    ('75edcd73-058b-504b-9db1-ee2b8a78c50e'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'Quel effet l’entraînement régulier a-t-il au repos ?', 'mcq', '["Il fait baisser le rythme cardiaque","Il l’augmente","Il ne change rien","Il augmente la température"]'::jsonb, 0, 'Le cœur envoie plus de sang à chaque battement.', 6),
    ('5291b0c7-c5a5-5e5b-b2b6-fa3bd4899910'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'Quand faut-il boire ?', 'mcq', '["Avant, pendant et après l’effort","Seulement après","Seulement quand on a soif","Le moins possible"]'::jsonb, 0, 'La soif apparaît quand la déshydratation a commencé.', 7),
    ('1f9e8fcb-6c9e-56a4-a416-b1b6229eca7b'::uuid, 'd46337ad-e240-5b55-b866-79890de2a19c'::uuid, 'Une douleur vive pendant l’effort doit être surmontée par courage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une information : on s’arrête et on prévient.', 8),
    ('d47aed31-7e96-515f-98db-784bd284d329'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'De combien d’heures de sommeil un adolescent a-t-il besoin ?', 'mcq', '["8 à 10 heures","5 à 6 heures","12 heures","7 heures maximum"]'::jsonb, 0, 'C’est pendant le sommeil que le corps répare et consolide.', 1),
    ('14b7ffcd-689f-54db-ae28-561e4529506f'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'Que fait le corps pendant le sommeil ?', 'mcq', '["Il répare les muscles et consolide les apprentissages","Il ne fait rien","Il brûle des calories seulement","Il digère uniquement"]'::jsonb, 0, 'Y compris les apprentissages moteurs.', 2),
    ('27f34e18-8beb-5b55-9499-0105fa44092f'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'Pourquoi les écrans nuisent-ils au sommeil ?', 'mcq', '["La lumière bleue retarde la sécrétion de mélatonine","Ils chauffent la pièce","Ils font du bruit","Ils fatiguent les yeux seulement"]'::jsonb, 0, 'L’endormissement est décalé.', 3),
    ('f2a99739-e4c0-54a3-a58b-14a7f9968c6d'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'Quel nutriment est le carburant principal de l’effort ?', 'mcq', '["Les glucides complexes","Les lipides","Les protéines","Les vitamines"]'::jsonb, 0, 'Pâtes, riz, pain, légumes secs.', 4),
    ('180b20ca-8ac4-532f-a9ec-9edcd4e6ba96'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'Quelle est la seule boisson indispensable ?', 'mcq', '["L’eau","Les boissons énergisantes","Le jus de fruit","Le lait"]'::jsonb, 0, 'Les boissons énergisantes sont inutiles et parfois dangereuses.', 5),
    ('d6005125-e0c7-5432-8376-6228af47f32c'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'Combien de minutes d’activité par jour l’OMS recommande-t-elle aux 5-17 ans ?', 'mcq', '["Au moins 60 minutes","15 minutes","30 minutes","2 heures"]'::jsonb, 0, 'Marcher et faire du vélo comptent.', 6),
    ('8b7b98cf-1d66-5d1d-9160-1f7feed09f7f'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'La sédentarité est-elle compensée par une séance de sport ?', 'mcq', '["Non, c’est un risque distinct du manque de sport","Oui, entièrement","Oui, si la séance est longue","La question ne se pose pas"]'::jsonb, 0, 'Se lever quelques minutes chaque heure compte.', 7),
    ('8bcf8546-2784-5e50-a027-6fd3177d45f9'::uuid, '81d8e977-3914-5fc1-aa0d-17fa715425f3'::uuid, 'Un adolescent sportif a besoin de compléments protéinés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une alimentation variée suffit ; à cet âge, le premier facteur est le sommeil.', 8),
    ('678907db-c97d-5604-9f7c-d2f65d776edb'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Pourquoi les rôles sont-ils évalués en EPS ?', 'mcq', '["Ils demandent de comprendre l’activité, pas seulement de la subir","Pour occuper les élèves dispensés","Pour gagner du temps","Ils ne sont pas évalués"]'::jsonb, 0, 'Au même titre que la performance.', 1),
    ('e25fc092-25a1-5fe7-bcbe-85a026c060c7'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Que suppose le rôle d’arbitre ?', 'mcq', '["Connaître la règle, décider vite et assumer la contestation","Être le meilleur joueur","Être le plus âgé","Rester silencieux"]'::jsonb, 0, 'Un arbitre qui hésite perd le match.', 2),
    ('08da6f55-9293-560b-a751-0c7ee93be40b'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Que fait l’observateur ?', 'mcq', '["Il relève des données précises et chiffrées","Il donne son avis général","Il arbitre","Il ne fait rien"]'::jsonb, 0, '« 7 passes sur 10 » se travaille, « il a bien joué » non.', 3),
    ('a628b5bf-750f-542e-a918-ae42e821a51c'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Qu’est-ce qu’un bon conseil de coach ?', 'mcq', '["Précis et positif : « place-toi plus haut »","Général : « joue mieux »","Négatif mais franc","Silencieux"]'::jsonb, 0, 'Le conseil doit être actionnable.', 4),
    ('a5c6207e-ea20-5192-8fb6-5d97b275a1f6'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Que fait l’organisateur ?', 'mcq', '["Il installe le matériel, tient le score, équilibre les équipes","Il joue en premier","Il note les élèves","Il choisit l’activité"]'::jsonb, 0, 'Sans lui, la séance n’a pas lieu.', 5),
    ('96513219-10fe-59d2-b74c-4aeca4fefcab'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Qu’apprend-on en arbitrant ?', 'mcq', '["Ce qu’on ressent quand on est contesté","À courir plus vite","À marquer plus de points","Rien de particulier"]'::jsonb, 0, 'Cela change durablement la façon de jouer.', 6),
    ('458786d4-f585-5926-a036-6214bf2ce9bc'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Quelles compétences transférables les rôles développent-ils ?', 'mcq', '["Décider sous pression, formuler un retour, organiser un groupe","La vitesse de course","La force musculaire","La souplesse"]'::jsonb, 0, 'Elles servent bien au-delà du gymnase.', 7),
    ('50b926ae-34f1-54d2-8b9f-d36168c8bc26'::uuid, 'ba3e697c-e0f4-5802-8abc-d75515d864cc'::uuid, 'Contester systématiquement l’arbitre fait partie du jeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela désorganise la séance et rend le rôle intenable.', 8),
    ('36523c6e-b17b-5c4a-a366-57b623d3b760'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'À quoi sert la règle dans un sport ?', 'mcq', '["Elle crée le jeu en fixant ce qui compte","Elle empêche de jouer librement","Elle avantage les plus forts","Elle sert à punir"]'::jsonb, 0, 'Sans règle commune, il n’y a pas de match.', 1),
    ('c768ef7c-68b0-566b-b153-0b4506dcc247'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'Qu’est-ce que le fair-play ?', 'mcq', '["Respecter la règle et l’adversaire même sans y être obligé","Gagner à tout prix","Obéir à l’arbitre","Ne jamais protester"]'::jsonb, 0, 'Il commence là où finit la surveillance.', 2),
    ('993540ec-0787-5f78-b662-be32395ffaa7'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'Quelles sont les trois familles de règles ?', 'mcq', '["Règles de but, d’espace et de temps, de sécurité","Règles écrites, orales, tacites","Règles d’attaque, de défense, de repos","Règles simples, moyennes, complexes"]'::jsonb, 0, 'Chacune joue un rôle différent.', 3),
    ('78f59752-325c-5fc6-b317-6a389f54a872'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'Que perd le mauvais perdant ?', 'mcq', '["La possibilité d’identifier ce qu’il y avait à corriger","Des points","Le respect de l’arbitre","Rien"]'::jsonb, 0, 'Chercher une excuse empêche de progresser.', 4),
    ('845294b5-433f-5452-a876-ef54b51f1031'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'Que prouve une victoire obtenue en trichant ?', 'mcq', '["Rien, pas même à celui qui triche","Qu’on est le meilleur","Qu’on est malin","Que la règle est mauvaise"]'::jsonb, 0, 'Elle fait gagner un match et perdre l’essentiel.', 5),
    ('90cca1e0-39cb-5d2b-b02f-d5b339a5810b'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'Pourquoi le dopage est-il interdit ?', 'mcq', '["Il fausse la compétition et met la santé en danger","Il coûte cher","Il est difficile à obtenir","Il ne fonctionne pas"]'::jsonb, 0, 'Effets sur le cœur, les hormones, le psychisme.', 6),
    ('ddecd485-7e44-5e09-b94f-4e0a3a362fb3'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'Quelles sont les trois valeurs olympiques ?', 'mcq', '["Excellence, amitié, respect","Force, vitesse, endurance","Victoire, gloire, argent","Discipline, silence, obéissance"]'::jsonb, 0, 'Elles dépassent la performance.', 7),
    ('ddd6bf2a-5aa1-5e1b-9d5c-111905248029'::uuid, '62b1b5eb-e3e5-5b9a-8402-2d9dadea49dc'::uuid, 'Respecter la règle uniquement quand l’arbitre regarde, c’est du fair-play.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est de l’obéissance ; le fair-play commence quand personne ne surveille.', 8),
    ('fa27e165-79c2-5723-ab50-a337c445dd1f'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Pourquoi retire-t-on les bijoux avant une séance ?', 'mcq', '["Ils accrochent et blessent","Ils font du bruit","Ils ralentissent","C’est une tradition"]'::jsonb, 0, 'Bagues, colliers, montres, piercings.', 1),
    ('e5ea4a0e-8edb-596a-b7f9-6baad58de361'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Que signale une consigne de sécurité ?', 'mcq', '["La trace d’un accident réel qu’on ne veut pas revoir","Une précaution théorique","Une contrainte administrative","Une préférence du professeur"]'::jsonb, 0, 'Elles ne sont pas négociables.', 2),
    ('38df5243-5639-5f0e-aa58-7b543657e64b'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Qu’est-ce qu’un claquage ?', 'mcq', '["Une douleur musculaire brutale en plein effort","Une articulation tordue","Un os cassé","Un vertige"]'::jsonb, 0, 'L’entorse concerne l’articulation.', 3),
    ('f82c776a-50b4-535d-a01b-dc505ba8b746'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Que signifie le protocole RICE ?', 'mcq', '["Repos, glace, compression, élévation","Repos, immobilité, chaleur, examen","Respirer, isoler, calmer, évacuer","Rien de précis"]'::jsonb, 0, 'La glace jamais à même la peau.', 4),
    ('1a671178-c94f-5f24-b98f-3fad0c67d9e5'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Quel est l’ordre des gestes en cas d’accident ?', 'mcq', '["Protéger, alerter, secourir","Secourir, alerter, protéger","Alerter, protéger, secourir","Appeler les parents d’abord"]'::jsonb, 0, 'Sans se mettre soi-même en danger.', 5),
    ('34cb60fe-5b38-532a-bd6c-9dfe6302e5ce'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Quel numéro appeler pour une urgence médicale ?', 'mcq', '["Le 15","Le 17","Le 114","Le 119"]'::jsonb, 0, 'Le 112 fonctionne partout en Europe.', 6),
    ('3484cfb0-1fcb-5d40-ab09-98944367cccd'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Qu’apprend-on au PSC1 ?', 'mcq', '["Position latérale de sécurité, massage cardiaque, défibrillateur","Les règles du basket","L’échauffement","La natation"]'::jsonb, 0, 'Elle s’obtient dès le collège.', 7),
    ('03cab15e-cf77-5437-aee1-6e1f87001007'::uuid, '7212a320-3c56-570f-b73e-8d09209c17fb'::uuid, 'Au téléphone avec les secours, on peut raccrocher dès qu’on a donné l’adresse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne raccroche jamais le premier.', 8),
    ('2189c625-b34d-5b3e-a8fa-acb85dfdef4f'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'Combien de champs d’apprentissage compte le programme d’EPS ?', 'mcq', '["Quatre","Deux","Six","Trois"]'::jsonb, 0, 'Ce sont quatre familles de problèmes à résoudre.', 1),
    ('72a089cd-53ce-537d-b9de-cc99221002b2'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'Quel champ concerne l’athlétisme et la natation de vitesse ?', 'mcq', '["Produire une performance mesurée","Adapter son déplacement","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Il s’agit de se dépasser et de mesurer son progrès.', 2),
    ('9389872d-4ebb-5129-8ff0-d75dcde05d68'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'À quel champ appartient l’escalade ?', 'mcq', '["Adapter son déplacement à des environnements variés","Produire une performance mesurée","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Le milieu y est incertain.', 3),
    ('655461c0-10ee-5edd-854a-fe4981dbc005'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'Quel champ regroupe la danse et l’acrosport ?', 'mcq', '["S’exprimer devant les autres par une prestation artistique","Produire une performance","Conduire un affrontement","Adapter son déplacement"]'::jsonb, 0, 'Créer, répéter, présenter à un public.', 4),
    ('145294b2-6c3d-538f-aaef-05f1473b49da'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'À quel champ appartiennent le badminton et le handball ?', 'mcq', '["Conduire et maîtriser un affrontement","Produire une performance mesurée","S’exprimer devant les autres","Adapter son déplacement"]'::jsonb, 0, 'Il faut décider vite dans un rapport de force.', 5),
    ('f3b3a306-ba82-53b1-b6e5-775ccc250c29'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'Qu’évalue-t-on en EPS ?', 'mcq', '["La progression, la méthode, les rôles tenus et le respect, pas seulement la performance","Uniquement le chronomètre","Uniquement la force","La présence seule"]'::jsonb, 0, 'La performance n’est qu’un critère parmi d’autres.', 6),
    ('db6f6965-5c8e-574e-b7a5-52442f80fbd7'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'Qu’est-ce que l’AS du collège ?', 'mcq', '["L’association sportive, ouverte à tous le mercredi","Une compétition réservée aux meilleurs","Un examen","Une note de fin d’année"]'::jsonb, 0, 'Elle permet de découvrir d’autres activités.', 7),
    ('2cac2576-e837-5f46-b661-cd734bad7609'::uuid, '7654542f-7569-5836-9bb9-4ccb2d195ac8'::uuid, 'Le programme d’EPS est une liste de sports à pratiquer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un parcours organisé autour de quatre types de problèmes.', 8),
    ('7751b954-6998-55ac-adbc-e1bab543f544'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'Qu’est-ce qui distingue un élève qui progresse ?', 'mcq', '["Sa méthode, pas son niveau de départ","Son talent naturel","Sa taille","Sa force initiale"]'::jsonb, 0, 'On progresse par la répétition organisée.', 1),
    ('8c3f4154-91fb-5e48-8b9b-549160b3f74f'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'Qu’est-ce qu’un bon objectif ?', 'mcq', '["Précis, mesurable et atteignable","Ambitieux et vague","Fixé par le professeur seul","Le plus élevé possible"]'::jsonb, 0, '« Courir 8 minutes sans m’arrêter ».', 2),
    ('91176627-ba79-534c-8580-e03f7c97a37b'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'Pourquoi mesurer son niveau de départ ?', 'mcq', '["Sans mesure initiale, le progrès reste invisible","Pour se comparer aux autres","Pour être noté","Ce n’est pas utile"]'::jsonb, 0, 'Un progrès invisible décourage.', 3),
    ('2c4c9c33-d587-5c81-9553-f8e97b307b0a'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'Qu’est-ce qui fait le plus progresser ?', 'mcq', '["Trois séances courtes par semaine","Une seule longue séance","L’intensité maximale à chaque fois","Le repos complet"]'::jsonb, 0, 'Le corps s’adapte entre les séances.', 4),
    ('d70d5aaf-64ae-51bb-bb3d-902aaad06f74'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'Qu’est-ce que la surcompensation ?', 'mcq', '["L’adaptation du corps entre les séances","Un excès d’entraînement","Une blessure","Un échauffement long"]'::jsonb, 0, 'C’est pourquoi la régularité prime.', 5),
    ('8f70b370-405d-507e-8364-091566b1d5f5'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'Quel est le rôle de l’erreur dans l’apprentissage moteur ?', 'mcq', '["Elle en fait partie : un geste s’automatise après de nombreux échecs","Elle doit être évitée","Elle prouve un manque de talent","Elle n’a aucun rôle"]'::jsonb, 0, 'Refuser de rater, c’est refuser d’apprendre.', 6),
    ('01762d26-770e-5606-9589-3eac3cf8e5b1'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'Pourquoi se filmer ou se faire observer ?', 'mcq', '["Voir le geste de l’extérieur corrige plus vite que la sensation","Pour se comparer","Pour être noté","Pour le plaisir"]'::jsonb, 0, 'La sensation interne trompe souvent.', 7),
    ('94cf96a8-f577-532b-9c8b-6a58fb305573'::uuid, '9d06cfbe-0513-5244-ba1c-26c57cc29176'::uuid, 'On progresse surtout grâce à des dispositions naturelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la méthode et la régularité qui font la différence.', 8),
    ('dc611536-f51c-5fc8-8411-796bbbdad407'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'À quoi sert principalement l’échauffement ?', 'mcq', '["Préparer le corps à l’effort et réduire le risque de blessure","Fatiguer avant l’effort","Gagner du temps","Impressionner l’adversaire"]'::jsonb, 0, 'C’est la partie qui protège toutes les autres.', 1),
    ('9c1f78c2-c31b-5157-a8d4-2e8d67521828'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'De combien la température musculaire monte-t-elle ?', 'mcq', '["De 1 à 2 °C","De 10 °C","Elle ne change pas","De 5 °C"]'::jsonb, 0, 'Le muscle devient plus élastique.', 2),
    ('caaa4fd9-c033-5b35-816d-7d971e410681'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'Quels sont les trois temps de l’échauffement ?', 'mcq', '["Général, articulaire, spécifique","Étirements, sprint, repos","Course, saut, lancer","Léger, moyen, intense"]'::jsonb, 0, 'Du général vers le spécifique.', 3),
    ('8e14bbd0-d74c-5646-b173-755a0391a1f8'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'Combien de temps dure l’échauffement général ?', 'mcq', '["5 à 10 minutes","30 secondes","30 minutes","1 minute"]'::jsonb, 0, 'Activité douce et continue.', 4),
    ('a5379715-8115-5f6e-8fd4-0e84d41a0527'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'Quand faut-il faire les étirements longs ?', 'mcq', '["Après l’effort, au retour au calme","Avant l’effort","Pendant l’effort","Jamais"]'::jsonb, 0, 'Avant, ils diminuent temporairement la force.', 5),
    ('f2c71e53-cbc6-5583-8bd4-1339a4f965c4'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'Dans quel sens progresse un échauffement ?', 'mcq', '["Du lent vers le rapide et du général vers le spécifique","Du rapide vers le lent","Peu importe l’ordre","Du spécifique vers le général"]'::jsonb, 0, 'Commencer par un sprint blesse.', 6),
    ('0e6f10cf-8b90-5879-a607-7e9d5ff3abd3'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'À quoi sert le retour au calme ?', 'mcq', '["Faire redescendre le rythme cardiaque et faciliter la récupération","Gagner des points","Rien de particulier","Se réchauffer"]'::jsonb, 0, 'Environ 5 minutes d’activité douce.', 7),
    ('b66b62d4-d5cb-5cc2-a62f-305281ee88f4'::uuid, '9f712e08-e916-5b81-9805-bb95bef33fb1'::uuid, 'Les étirements avant l’effort préviennent les blessures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les étirements statiques avant l’effort diminuent la force sans protéger.', 8),
    ('cccd5aca-cbd2-5232-9241-cbf7f4528722'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'Que réclament les muscles pendant l’effort ?', 'mcq', '["Plus de dioxygène et de nutriments","Moins de sang","Du dioxyde de carbone","Du repos immédiat"]'::jsonb, 0, 'Le cœur et la respiration s’accélèrent pour les fournir.', 1),
    ('129b2b7f-fec7-5939-8903-611ea0726e9d'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'Qu’est-ce que le régime aérobie ?', 'mcq', '["Un effort modéré et long où le dioxygène suffit","Un sprint","Un effort sans respiration","Un effort au repos"]'::jsonb, 0, 'On peut parler en courant.', 2),
    ('725f0cc6-4ab0-5355-95c8-fbae0b212462'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'Que produit le corps en anaérobie ?', 'mcq', '["De l’acide lactique","Du dioxygène","De l’eau seulement","Du glucose"]'::jsonb, 0, 'D’où les jambes qui brûlent.', 3),
    ('34c40193-918f-533b-8e33-d16ee5dcecce'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'Comment estimer sa fréquence cardiaque maximale ?', 'mcq', '["220 moins l’âge","200 plus l’âge","Le double du pouls au repos","150 pour tout le monde"]'::jsonb, 0, 'À 13 ans, environ 207.', 4),
    ('b3a1c2d8-3d2f-5609-9103-8b60d748bc3c'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'À quelle intensité travaille-t-on l’endurance ?', 'mcq', '["Entre 60 et 75 % de la FCmax","À 100 %","À 30 %","Peu importe"]'::jsonb, 0, 'Une allure où l’on peut encore parler.', 5),
    ('4bf5a6a7-06cf-5937-8995-381d311a125e'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'Quel effet l’entraînement régulier a-t-il au repos ?', 'mcq', '["Il fait baisser le rythme cardiaque","Il l’augmente","Il ne change rien","Il augmente la température"]'::jsonb, 0, 'Le cœur envoie plus de sang à chaque battement.', 6),
    ('669fbe4e-3aaf-5ad3-a6fe-b9cdc157fe13'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'Quand faut-il boire ?', 'mcq', '["Avant, pendant et après l’effort","Seulement après","Seulement quand on a soif","Le moins possible"]'::jsonb, 0, 'La soif apparaît quand la déshydratation a commencé.', 7),
    ('2b8e933c-005e-5b18-97e3-7158d7ed4774'::uuid, '81d12063-e331-5f53-be95-16fa10f75132'::uuid, 'Une douleur vive pendant l’effort doit être surmontée par courage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une information : on s’arrête et on prévient.', 8),
    ('6c8c04cc-ad5a-58d2-99bd-ba8d081683a9'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'De combien d’heures de sommeil un adolescent a-t-il besoin ?', 'mcq', '["8 à 10 heures","5 à 6 heures","12 heures","7 heures maximum"]'::jsonb, 0, 'C’est pendant le sommeil que le corps répare et consolide.', 1),
    ('e21fdd8c-220e-5eff-b680-46c5593ff1df'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'Que fait le corps pendant le sommeil ?', 'mcq', '["Il répare les muscles et consolide les apprentissages","Il ne fait rien","Il brûle des calories seulement","Il digère uniquement"]'::jsonb, 0, 'Y compris les apprentissages moteurs.', 2),
    ('3ea89d42-1a7a-5499-88ba-73e52c517b31'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'Pourquoi les écrans nuisent-ils au sommeil ?', 'mcq', '["La lumière bleue retarde la sécrétion de mélatonine","Ils chauffent la pièce","Ils font du bruit","Ils fatiguent les yeux seulement"]'::jsonb, 0, 'L’endormissement est décalé.', 3),
    ('ce04fdf6-89bb-50ed-be5c-d44079b0dde9'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'Quel nutriment est le carburant principal de l’effort ?', 'mcq', '["Les glucides complexes","Les lipides","Les protéines","Les vitamines"]'::jsonb, 0, 'Pâtes, riz, pain, légumes secs.', 4),
    ('0c21164b-2925-58c3-b52e-a5ac63ae942a'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'Quelle est la seule boisson indispensable ?', 'mcq', '["L’eau","Les boissons énergisantes","Le jus de fruit","Le lait"]'::jsonb, 0, 'Les boissons énergisantes sont inutiles et parfois dangereuses.', 5),
    ('2a921339-a1e9-549f-b934-d9874dc84dff'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'Combien de minutes d’activité par jour l’OMS recommande-t-elle aux 5-17 ans ?', 'mcq', '["Au moins 60 minutes","15 minutes","30 minutes","2 heures"]'::jsonb, 0, 'Marcher et faire du vélo comptent.', 6),
    ('5a956f78-018c-5bf6-951a-32d6a57f5126'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'La sédentarité est-elle compensée par une séance de sport ?', 'mcq', '["Non, c’est un risque distinct du manque de sport","Oui, entièrement","Oui, si la séance est longue","La question ne se pose pas"]'::jsonb, 0, 'Se lever quelques minutes chaque heure compte.', 7),
    ('9d6620f3-7154-5bef-98eb-819817687f3d'::uuid, '31010047-4e4c-5c13-a489-c2716934ab57'::uuid, 'Un adolescent sportif a besoin de compléments protéinés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une alimentation variée suffit ; à cet âge, le premier facteur est le sommeil.', 8),
    ('f4afdbb0-3766-5e48-8e7c-5f590b3c340f'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Pourquoi les rôles sont-ils évalués en EPS ?', 'mcq', '["Ils demandent de comprendre l’activité, pas seulement de la subir","Pour occuper les élèves dispensés","Pour gagner du temps","Ils ne sont pas évalués"]'::jsonb, 0, 'Au même titre que la performance.', 1),
    ('d1389c3f-5ba9-5d52-9264-dc0187e17792'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Que suppose le rôle d’arbitre ?', 'mcq', '["Connaître la règle, décider vite et assumer la contestation","Être le meilleur joueur","Être le plus âgé","Rester silencieux"]'::jsonb, 0, 'Un arbitre qui hésite perd le match.', 2),
    ('1712458f-959f-551b-873e-e6f07fe2ecc5'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Que fait l’observateur ?', 'mcq', '["Il relève des données précises et chiffrées","Il donne son avis général","Il arbitre","Il ne fait rien"]'::jsonb, 0, '« 7 passes sur 10 » se travaille, « il a bien joué » non.', 3),
    ('b69a3f5a-e7e0-575c-af72-0721c9bc773c'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Qu’est-ce qu’un bon conseil de coach ?', 'mcq', '["Précis et positif : « place-toi plus haut »","Général : « joue mieux »","Négatif mais franc","Silencieux"]'::jsonb, 0, 'Le conseil doit être actionnable.', 4),
    ('544c4628-c199-5026-8161-0a7742b3cbc6'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Que fait l’organisateur ?', 'mcq', '["Il installe le matériel, tient le score, équilibre les équipes","Il joue en premier","Il note les élèves","Il choisit l’activité"]'::jsonb, 0, 'Sans lui, la séance n’a pas lieu.', 5),
    ('f526d468-d783-510d-8a08-d267012ae42f'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Qu’apprend-on en arbitrant ?', 'mcq', '["Ce qu’on ressent quand on est contesté","À courir plus vite","À marquer plus de points","Rien de particulier"]'::jsonb, 0, 'Cela change durablement la façon de jouer.', 6),
    ('82fb58fe-20f3-57a5-a106-41d096a6878b'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Quelles compétences transférables les rôles développent-ils ?', 'mcq', '["Décider sous pression, formuler un retour, organiser un groupe","La vitesse de course","La force musculaire","La souplesse"]'::jsonb, 0, 'Elles servent bien au-delà du gymnase.', 7),
    ('f465830d-1314-5f14-b156-428345acd8c2'::uuid, '4173e4b1-a523-57b5-aeb1-0f49c9f86f5c'::uuid, 'Contester systématiquement l’arbitre fait partie du jeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela désorganise la séance et rend le rôle intenable.', 8),
    ('baaf4e66-0371-5566-9bd8-e7ee6a07c9ac'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'À quoi sert la règle dans un sport ?', 'mcq', '["Elle crée le jeu en fixant ce qui compte","Elle empêche de jouer librement","Elle avantage les plus forts","Elle sert à punir"]'::jsonb, 0, 'Sans règle commune, il n’y a pas de match.', 1),
    ('3b8703be-30cf-55d4-b7b7-ba26414da05b'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'Qu’est-ce que le fair-play ?', 'mcq', '["Respecter la règle et l’adversaire même sans y être obligé","Gagner à tout prix","Obéir à l’arbitre","Ne jamais protester"]'::jsonb, 0, 'Il commence là où finit la surveillance.', 2),
    ('ae0a87f1-aab2-56de-a90a-ede9bce79be5'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'Quelles sont les trois familles de règles ?', 'mcq', '["Règles de but, d’espace et de temps, de sécurité","Règles écrites, orales, tacites","Règles d’attaque, de défense, de repos","Règles simples, moyennes, complexes"]'::jsonb, 0, 'Chacune joue un rôle différent.', 3),
    ('47d1a06f-6b40-5720-8507-fc987a4016d3'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'Que perd le mauvais perdant ?', 'mcq', '["La possibilité d’identifier ce qu’il y avait à corriger","Des points","Le respect de l’arbitre","Rien"]'::jsonb, 0, 'Chercher une excuse empêche de progresser.', 4),
    ('deff7765-df8b-5936-b452-7685e91acfd3'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'Que prouve une victoire obtenue en trichant ?', 'mcq', '["Rien, pas même à celui qui triche","Qu’on est le meilleur","Qu’on est malin","Que la règle est mauvaise"]'::jsonb, 0, 'Elle fait gagner un match et perdre l’essentiel.', 5),
    ('e0c1a9a8-6378-5dbf-b82f-47093f9c85b0'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'Pourquoi le dopage est-il interdit ?', 'mcq', '["Il fausse la compétition et met la santé en danger","Il coûte cher","Il est difficile à obtenir","Il ne fonctionne pas"]'::jsonb, 0, 'Effets sur le cœur, les hormones, le psychisme.', 6),
    ('d2b302d4-018d-5c98-b156-f5a7f8b829fe'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'Quelles sont les trois valeurs olympiques ?', 'mcq', '["Excellence, amitié, respect","Force, vitesse, endurance","Victoire, gloire, argent","Discipline, silence, obéissance"]'::jsonb, 0, 'Elles dépassent la performance.', 7),
    ('1eb1dc21-c7a3-5e3b-a82b-0751ca90cc4d'::uuid, '14fb5ef5-ce13-5f2d-903d-ab63e2b4f1b9'::uuid, 'Respecter la règle uniquement quand l’arbitre regarde, c’est du fair-play.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est de l’obéissance ; le fair-play commence quand personne ne surveille.', 8),
    ('392c7b95-0fd4-5607-b913-26bb958fad55'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Pourquoi retire-t-on les bijoux avant une séance ?', 'mcq', '["Ils accrochent et blessent","Ils font du bruit","Ils ralentissent","C’est une tradition"]'::jsonb, 0, 'Bagues, colliers, montres, piercings.', 1),
    ('c34920a7-8593-525a-ab21-d82b0e73d488'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Que signale une consigne de sécurité ?', 'mcq', '["La trace d’un accident réel qu’on ne veut pas revoir","Une précaution théorique","Une contrainte administrative","Une préférence du professeur"]'::jsonb, 0, 'Elles ne sont pas négociables.', 2),
    ('99d3b8d2-6cd8-56b2-9a30-c9f1b23af434'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Qu’est-ce qu’un claquage ?', 'mcq', '["Une douleur musculaire brutale en plein effort","Une articulation tordue","Un os cassé","Un vertige"]'::jsonb, 0, 'L’entorse concerne l’articulation.', 3),
    ('d77b90e2-6017-549a-aac9-e37c834841cc'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Que signifie le protocole RICE ?', 'mcq', '["Repos, glace, compression, élévation","Repos, immobilité, chaleur, examen","Respirer, isoler, calmer, évacuer","Rien de précis"]'::jsonb, 0, 'La glace jamais à même la peau.', 4),
    ('5d5d0ec8-4286-5f69-a173-b0b81cf1c3c2'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Quel est l’ordre des gestes en cas d’accident ?', 'mcq', '["Protéger, alerter, secourir","Secourir, alerter, protéger","Alerter, protéger, secourir","Appeler les parents d’abord"]'::jsonb, 0, 'Sans se mettre soi-même en danger.', 5),
    ('011ba455-9ebe-5963-8c29-8099d255beae'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Quel numéro appeler pour une urgence médicale ?', 'mcq', '["Le 15","Le 17","Le 114","Le 119"]'::jsonb, 0, 'Le 112 fonctionne partout en Europe.', 6),
    ('ad142dde-1c29-57c7-b815-e917b6577899'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Qu’apprend-on au PSC1 ?', 'mcq', '["Position latérale de sécurité, massage cardiaque, défibrillateur","Les règles du basket","L’échauffement","La natation"]'::jsonb, 0, 'Elle s’obtient dès le collège.', 7),
    ('b126f1f5-ac78-52a8-a62c-03b3387dbdc7'::uuid, '93fa6faf-90f0-5cc2-bc01-a4c2c41e0487'::uuid, 'Au téléphone avec les secours, on peut raccrocher dès qu’on a donné l’adresse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne raccroche jamais le premier.', 8),
    ('f30ce326-866a-5fea-9e7f-b8063a24c62b'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'Combien de champs d’apprentissage compte le programme d’EPS ?', 'mcq', '["Quatre","Deux","Six","Trois"]'::jsonb, 0, 'Ce sont quatre familles de problèmes à résoudre.', 1),
    ('88a5e39d-639d-50db-b3ba-a2b0e1978731'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'Quel champ concerne l’athlétisme et la natation de vitesse ?', 'mcq', '["Produire une performance mesurée","Adapter son déplacement","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Il s’agit de se dépasser et de mesurer son progrès.', 2),
    ('2acb2303-777c-5b6c-b6c2-e452e46f8d71'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'À quel champ appartient l’escalade ?', 'mcq', '["Adapter son déplacement à des environnements variés","Produire une performance mesurée","S’exprimer devant les autres","Conduire un affrontement"]'::jsonb, 0, 'Le milieu y est incertain.', 3),
    ('282890b3-60b5-52aa-96c5-5d173c6dd406'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'Quel champ regroupe la danse et l’acrosport ?', 'mcq', '["S’exprimer devant les autres par une prestation artistique","Produire une performance","Conduire un affrontement","Adapter son déplacement"]'::jsonb, 0, 'Créer, répéter, présenter à un public.', 4),
    ('aa6a832b-844f-5116-8acc-b9b3f715f313'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'À quel champ appartiennent le badminton et le handball ?', 'mcq', '["Conduire et maîtriser un affrontement","Produire une performance mesurée","S’exprimer devant les autres","Adapter son déplacement"]'::jsonb, 0, 'Il faut décider vite dans un rapport de force.', 5),
    ('b69d5894-935d-544e-b131-853d2d6b0f0d'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'Qu’évalue-t-on en EPS ?', 'mcq', '["La progression, la méthode, les rôles tenus et le respect, pas seulement la performance","Uniquement le chronomètre","Uniquement la force","La présence seule"]'::jsonb, 0, 'La performance n’est qu’un critère parmi d’autres.', 6),
    ('e986446d-2a76-5103-9817-c1ddad1861f3'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'Qu’est-ce que l’AS du collège ?', 'mcq', '["L’association sportive, ouverte à tous le mercredi","Une compétition réservée aux meilleurs","Un examen","Une note de fin d’année"]'::jsonb, 0, 'Elle permet de découvrir d’autres activités.', 7),
    ('a28833d0-cdba-54f9-9696-548588879d4e'::uuid, '73a6618f-0333-55a0-90b4-51ae20d567be'::uuid, 'Le programme d’EPS est une liste de sports à pratiquer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un parcours organisé autour de quatre types de problèmes.', 8),
    ('a3d2cf4a-310e-5fc1-bb05-5ef76e41cc05'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'Qu’est-ce qui distingue un élève qui progresse ?', 'mcq', '["Sa méthode, pas son niveau de départ","Son talent naturel","Sa taille","Sa force initiale"]'::jsonb, 0, 'On progresse par la répétition organisée.', 1),
    ('3c3b5ba0-ccc9-5b18-a57a-f8d7dbcf306c'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'Qu’est-ce qu’un bon objectif ?', 'mcq', '["Précis, mesurable et atteignable","Ambitieux et vague","Fixé par le professeur seul","Le plus élevé possible"]'::jsonb, 0, '« Courir 8 minutes sans m’arrêter ».', 2),
    ('22d74b48-2961-5f78-b65b-5dffd4467b03'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'Pourquoi mesurer son niveau de départ ?', 'mcq', '["Sans mesure initiale, le progrès reste invisible","Pour se comparer aux autres","Pour être noté","Ce n’est pas utile"]'::jsonb, 0, 'Un progrès invisible décourage.', 3),
    ('d3e83809-b8cd-5b62-ac56-ceb7c61f045e'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'Qu’est-ce qui fait le plus progresser ?', 'mcq', '["Trois séances courtes par semaine","Une seule longue séance","L’intensité maximale à chaque fois","Le repos complet"]'::jsonb, 0, 'Le corps s’adapte entre les séances.', 4),
    ('17af30e5-32e7-5380-843c-d787257d1a68'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'Qu’est-ce que la surcompensation ?', 'mcq', '["L’adaptation du corps entre les séances","Un excès d’entraînement","Une blessure","Un échauffement long"]'::jsonb, 0, 'C’est pourquoi la régularité prime.', 5),
    ('218af849-8e22-5b35-820f-dfa7558e462f'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'Quel est le rôle de l’erreur dans l’apprentissage moteur ?', 'mcq', '["Elle en fait partie : un geste s’automatise après de nombreux échecs","Elle doit être évitée","Elle prouve un manque de talent","Elle n’a aucun rôle"]'::jsonb, 0, 'Refuser de rater, c’est refuser d’apprendre.', 6),
    ('cd7c8fe5-3a42-5104-b080-12668207c787'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'Pourquoi se filmer ou se faire observer ?', 'mcq', '["Voir le geste de l’extérieur corrige plus vite que la sensation","Pour se comparer","Pour être noté","Pour le plaisir"]'::jsonb, 0, 'La sensation interne trompe souvent.', 7),
    ('5f19b334-890a-5855-a1cc-e890f4445cac'::uuid, 'b0bc8e76-92f7-549d-9c8d-3e0f82ed0208'::uuid, 'On progresse surtout grâce à des dispositions naturelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la méthode et la régularité qui font la différence.', 8),
    ('386e77f5-451e-503e-8ef8-50d1ca17f643'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'À quoi sert principalement l’échauffement ?', 'mcq', '["Préparer le corps à l’effort et réduire le risque de blessure","Fatiguer avant l’effort","Gagner du temps","Impressionner l’adversaire"]'::jsonb, 0, 'C’est la partie qui protège toutes les autres.', 1),
    ('7eb48edf-106b-512c-b9b5-f3c574fa4db4'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'De combien la température musculaire monte-t-elle ?', 'mcq', '["De 1 à 2 °C","De 10 °C","Elle ne change pas","De 5 °C"]'::jsonb, 0, 'Le muscle devient plus élastique.', 2),
    ('9f914519-e8a2-5f6c-b996-20037e9aab69'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'Quels sont les trois temps de l’échauffement ?', 'mcq', '["Général, articulaire, spécifique","Étirements, sprint, repos","Course, saut, lancer","Léger, moyen, intense"]'::jsonb, 0, 'Du général vers le spécifique.', 3),
    ('25aaa326-070b-5063-b433-02c231f7f7ca'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'Combien de temps dure l’échauffement général ?', 'mcq', '["5 à 10 minutes","30 secondes","30 minutes","1 minute"]'::jsonb, 0, 'Activité douce et continue.', 4),
    ('6bedf054-580e-518d-a95f-e1742bdc84e0'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'Quand faut-il faire les étirements longs ?', 'mcq', '["Après l’effort, au retour au calme","Avant l’effort","Pendant l’effort","Jamais"]'::jsonb, 0, 'Avant, ils diminuent temporairement la force.', 5),
    ('00f7901d-8994-55d6-a5ec-583b4aa5d135'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'Dans quel sens progresse un échauffement ?', 'mcq', '["Du lent vers le rapide et du général vers le spécifique","Du rapide vers le lent","Peu importe l’ordre","Du spécifique vers le général"]'::jsonb, 0, 'Commencer par un sprint blesse.', 6),
    ('e5517035-4e18-5bb6-ae20-31dac5029ef4'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'À quoi sert le retour au calme ?', 'mcq', '["Faire redescendre le rythme cardiaque et faciliter la récupération","Gagner des points","Rien de particulier","Se réchauffer"]'::jsonb, 0, 'Environ 5 minutes d’activité douce.', 7),
    ('4bc3fe5f-956e-575f-8de0-9e2d60889f7c'::uuid, '29a19f77-1c11-599d-9f06-fb8ac4b0a5ce'::uuid, 'Les étirements avant l’effort préviennent les blessures.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les étirements statiques avant l’effort diminuent la force sans protéger.', 8),
    ('70ac4c27-b08a-5861-a1f0-a44ec76a7260'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'Que réclament les muscles pendant l’effort ?', 'mcq', '["Plus de dioxygène et de nutriments","Moins de sang","Du dioxyde de carbone","Du repos immédiat"]'::jsonb, 0, 'Le cœur et la respiration s’accélèrent pour les fournir.', 1),
    ('50160487-d21b-5181-84c9-7a5f03bfeef6'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'Qu’est-ce que le régime aérobie ?', 'mcq', '["Un effort modéré et long où le dioxygène suffit","Un sprint","Un effort sans respiration","Un effort au repos"]'::jsonb, 0, 'On peut parler en courant.', 2),
    ('ff14e44b-6933-5804-897a-e569eb351904'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'Que produit le corps en anaérobie ?', 'mcq', '["De l’acide lactique","Du dioxygène","De l’eau seulement","Du glucose"]'::jsonb, 0, 'D’où les jambes qui brûlent.', 3),
    ('60d951d9-db0f-518e-a2df-e3696b8f8612'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'Comment estimer sa fréquence cardiaque maximale ?', 'mcq', '["220 moins l’âge","200 plus l’âge","Le double du pouls au repos","150 pour tout le monde"]'::jsonb, 0, 'À 13 ans, environ 207.', 4),
    ('56784b55-1746-5334-85b0-0e94ff880d07'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'À quelle intensité travaille-t-on l’endurance ?', 'mcq', '["Entre 60 et 75 % de la FCmax","À 100 %","À 30 %","Peu importe"]'::jsonb, 0, 'Une allure où l’on peut encore parler.', 5),
    ('45257dfb-f936-5c38-a301-02c111f0324e'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'Quel effet l’entraînement régulier a-t-il au repos ?', 'mcq', '["Il fait baisser le rythme cardiaque","Il l’augmente","Il ne change rien","Il augmente la température"]'::jsonb, 0, 'Le cœur envoie plus de sang à chaque battement.', 6),
    ('ebee1eb2-eea3-5a52-93a4-a0380fd953ac'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'Quand faut-il boire ?', 'mcq', '["Avant, pendant et après l’effort","Seulement après","Seulement quand on a soif","Le moins possible"]'::jsonb, 0, 'La soif apparaît quand la déshydratation a commencé.', 7),
    ('8e9f2afc-44b8-55bc-97ef-2a17edb57d97'::uuid, '985fc525-4d04-57ca-9590-83468ac2169e'::uuid, 'Une douleur vive pendant l’effort doit être surmontée par courage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une information : on s’arrête et on prévient.', 8),
    ('0f7f7346-af33-5a3c-837a-61303d495405'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'De combien d’heures de sommeil un adolescent a-t-il besoin ?', 'mcq', '["8 à 10 heures","5 à 6 heures","12 heures","7 heures maximum"]'::jsonb, 0, 'C’est pendant le sommeil que le corps répare et consolide.', 1),
    ('25eea310-d3fa-5c47-b6f8-1826bd5ff09b'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'Que fait le corps pendant le sommeil ?', 'mcq', '["Il répare les muscles et consolide les apprentissages","Il ne fait rien","Il brûle des calories seulement","Il digère uniquement"]'::jsonb, 0, 'Y compris les apprentissages moteurs.', 2),
    ('67e333a8-381e-5369-913f-d48ae6605ced'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'Pourquoi les écrans nuisent-ils au sommeil ?', 'mcq', '["La lumière bleue retarde la sécrétion de mélatonine","Ils chauffent la pièce","Ils font du bruit","Ils fatiguent les yeux seulement"]'::jsonb, 0, 'L’endormissement est décalé.', 3),
    ('298a24ee-5f2c-5e04-be0a-caeafd703608'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'Quel nutriment est le carburant principal de l’effort ?', 'mcq', '["Les glucides complexes","Les lipides","Les protéines","Les vitamines"]'::jsonb, 0, 'Pâtes, riz, pain, légumes secs.', 4),
    ('3cfd2863-4aca-5615-bcf9-ad823e4e195e'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'Quelle est la seule boisson indispensable ?', 'mcq', '["L’eau","Les boissons énergisantes","Le jus de fruit","Le lait"]'::jsonb, 0, 'Les boissons énergisantes sont inutiles et parfois dangereuses.', 5),
    ('9a901d9d-64bd-5a1a-a835-9e6f568677e2'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'Combien de minutes d’activité par jour l’OMS recommande-t-elle aux 5-17 ans ?', 'mcq', '["Au moins 60 minutes","15 minutes","30 minutes","2 heures"]'::jsonb, 0, 'Marcher et faire du vélo comptent.', 6),
    ('05af33d7-942b-5f8a-967d-766890fa9a81'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'La sédentarité est-elle compensée par une séance de sport ?', 'mcq', '["Non, c’est un risque distinct du manque de sport","Oui, entièrement","Oui, si la séance est longue","La question ne se pose pas"]'::jsonb, 0, 'Se lever quelques minutes chaque heure compte.', 7),
    ('c7463dfd-96f1-5b42-9c30-762eb47e8b06'::uuid, '9434277c-0ef7-5cce-87b0-7aa3d5cc8fa1'::uuid, 'Un adolescent sportif a besoin de compléments protéinés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une alimentation variée suffit ; à cet âge, le premier facteur est le sommeil.', 8),
    ('6fe6c478-860d-5f3b-8d22-0a53bca7eec9'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Pourquoi les rôles sont-ils évalués en EPS ?', 'mcq', '["Ils demandent de comprendre l’activité, pas seulement de la subir","Pour occuper les élèves dispensés","Pour gagner du temps","Ils ne sont pas évalués"]'::jsonb, 0, 'Au même titre que la performance.', 1),
    ('a15079d0-fbb2-587a-be61-cf43f8978a1b'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Que suppose le rôle d’arbitre ?', 'mcq', '["Connaître la règle, décider vite et assumer la contestation","Être le meilleur joueur","Être le plus âgé","Rester silencieux"]'::jsonb, 0, 'Un arbitre qui hésite perd le match.', 2),
    ('13fbdfb2-7a7f-5957-a699-b87dc24473cb'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Que fait l’observateur ?', 'mcq', '["Il relève des données précises et chiffrées","Il donne son avis général","Il arbitre","Il ne fait rien"]'::jsonb, 0, '« 7 passes sur 10 » se travaille, « il a bien joué » non.', 3),
    ('e148bba8-bf92-52c7-8f7c-c60485810175'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Qu’est-ce qu’un bon conseil de coach ?', 'mcq', '["Précis et positif : « place-toi plus haut »","Général : « joue mieux »","Négatif mais franc","Silencieux"]'::jsonb, 0, 'Le conseil doit être actionnable.', 4),
    ('6394b25c-192e-57dc-a8aa-4076cacda380'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Que fait l’organisateur ?', 'mcq', '["Il installe le matériel, tient le score, équilibre les équipes","Il joue en premier","Il note les élèves","Il choisit l’activité"]'::jsonb, 0, 'Sans lui, la séance n’a pas lieu.', 5),
    ('2b9a7bcc-5973-51d7-bcf0-9ea0f6d078a0'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Qu’apprend-on en arbitrant ?', 'mcq', '["Ce qu’on ressent quand on est contesté","À courir plus vite","À marquer plus de points","Rien de particulier"]'::jsonb, 0, 'Cela change durablement la façon de jouer.', 6),
    ('59dcf292-d32a-5234-bf3b-c3e175bdd987'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Quelles compétences transférables les rôles développent-ils ?', 'mcq', '["Décider sous pression, formuler un retour, organiser un groupe","La vitesse de course","La force musculaire","La souplesse"]'::jsonb, 0, 'Elles servent bien au-delà du gymnase.', 7),
    ('6048267b-cade-5a9b-849c-e39125b18b01'::uuid, '8f09ea63-5642-5c0e-b8da-34836e09d27b'::uuid, 'Contester systématiquement l’arbitre fait partie du jeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela désorganise la séance et rend le rôle intenable.', 8),
    ('4cfe2e81-41b4-5ed0-a5cf-8f0f193f9e37'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'À quoi sert la règle dans un sport ?', 'mcq', '["Elle crée le jeu en fixant ce qui compte","Elle empêche de jouer librement","Elle avantage les plus forts","Elle sert à punir"]'::jsonb, 0, 'Sans règle commune, il n’y a pas de match.', 1),
    ('c6e4ccba-a61d-5603-914a-02b9ddd5223b'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'Qu’est-ce que le fair-play ?', 'mcq', '["Respecter la règle et l’adversaire même sans y être obligé","Gagner à tout prix","Obéir à l’arbitre","Ne jamais protester"]'::jsonb, 0, 'Il commence là où finit la surveillance.', 2),
    ('eb15808a-018c-5a16-a3cb-4cfc8d8fc5ec'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'Quelles sont les trois familles de règles ?', 'mcq', '["Règles de but, d’espace et de temps, de sécurité","Règles écrites, orales, tacites","Règles d’attaque, de défense, de repos","Règles simples, moyennes, complexes"]'::jsonb, 0, 'Chacune joue un rôle différent.', 3),
    ('59b89c11-9868-5c72-a2ef-9c689aba6257'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'Que perd le mauvais perdant ?', 'mcq', '["La possibilité d’identifier ce qu’il y avait à corriger","Des points","Le respect de l’arbitre","Rien"]'::jsonb, 0, 'Chercher une excuse empêche de progresser.', 4),
    ('7cae6163-bc53-5fe0-b876-8939b7536c9b'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'Que prouve une victoire obtenue en trichant ?', 'mcq', '["Rien, pas même à celui qui triche","Qu’on est le meilleur","Qu’on est malin","Que la règle est mauvaise"]'::jsonb, 0, 'Elle fait gagner un match et perdre l’essentiel.', 5),
    ('153ad478-63eb-565a-a59f-c75acb28d744'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'Pourquoi le dopage est-il interdit ?', 'mcq', '["Il fausse la compétition et met la santé en danger","Il coûte cher","Il est difficile à obtenir","Il ne fonctionne pas"]'::jsonb, 0, 'Effets sur le cœur, les hormones, le psychisme.', 6),
    ('fdfa0ded-7624-5904-b0ae-1cf7bab605b1'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'Quelles sont les trois valeurs olympiques ?', 'mcq', '["Excellence, amitié, respect","Force, vitesse, endurance","Victoire, gloire, argent","Discipline, silence, obéissance"]'::jsonb, 0, 'Elles dépassent la performance.', 7),
    ('27e6f146-fe3f-593a-a9b0-7566e918b233'::uuid, 'fe0f0de8-9097-5d02-864e-3c6bd0b98946'::uuid, 'Respecter la règle uniquement quand l’arbitre regarde, c’est du fair-play.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est de l’obéissance ; le fair-play commence quand personne ne surveille.', 8),
    ('d01ffc45-f5cb-5e8d-b5d1-48c512535feb'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Pourquoi retire-t-on les bijoux avant une séance ?', 'mcq', '["Ils accrochent et blessent","Ils font du bruit","Ils ralentissent","C’est une tradition"]'::jsonb, 0, 'Bagues, colliers, montres, piercings.', 1),
    ('5fe08e3f-13ac-5003-a534-f76f6bdc7919'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Que signale une consigne de sécurité ?', 'mcq', '["La trace d’un accident réel qu’on ne veut pas revoir","Une précaution théorique","Une contrainte administrative","Une préférence du professeur"]'::jsonb, 0, 'Elles ne sont pas négociables.', 2),
    ('e6ccbd13-4d58-5c07-a70e-be796ee2410a'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Qu’est-ce qu’un claquage ?', 'mcq', '["Une douleur musculaire brutale en plein effort","Une articulation tordue","Un os cassé","Un vertige"]'::jsonb, 0, 'L’entorse concerne l’articulation.', 3),
    ('322f0850-8d39-514a-bf4b-538f39dc6bc1'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Que signifie le protocole RICE ?', 'mcq', '["Repos, glace, compression, élévation","Repos, immobilité, chaleur, examen","Respirer, isoler, calmer, évacuer","Rien de précis"]'::jsonb, 0, 'La glace jamais à même la peau.', 4),
    ('010fe680-8c04-5175-8899-2f223bf77817'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Quel est l’ordre des gestes en cas d’accident ?', 'mcq', '["Protéger, alerter, secourir","Secourir, alerter, protéger","Alerter, protéger, secourir","Appeler les parents d’abord"]'::jsonb, 0, 'Sans se mettre soi-même en danger.', 5),
    ('b12839fe-9405-5694-9a2f-fd03f375bc89'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Quel numéro appeler pour une urgence médicale ?', 'mcq', '["Le 15","Le 17","Le 114","Le 119"]'::jsonb, 0, 'Le 112 fonctionne partout en Europe.', 6),
    ('e3f89a31-8490-5eb7-b1e4-163a1211406c'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Qu’apprend-on au PSC1 ?', 'mcq', '["Position latérale de sécurité, massage cardiaque, défibrillateur","Les règles du basket","L’échauffement","La natation"]'::jsonb, 0, 'Elle s’obtient dès le collège.', 7),
    ('b5b77aea-20c0-5305-aadd-3c2e24a2e567'::uuid, '3bf497c5-3f88-58c4-83aa-b31561d62ce5'::uuid, 'Au téléphone avec les secours, on peut raccrocher dès qu’on a donné l’adresse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne raccroche jamais le premier.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('sport');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('sport')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 339 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 339 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
